const csv = `name,ip,type
router,192.168.1.1,router
macbook, 192.168.1.23 ,laptop

pi,192.168.1.50,server
`;

function parseCsv(text) {
  const lines = text.split('\n').map((l) => l.trim()).filter((l) => l !== '');
  const keys = lines[0].split(',').map((k) => k.trim());
  return lines.slice(1).map((line) => {
    const fields = line.split(',').map((f) => f.trim());
    return Object.fromEntries(keys.map((k, i) => [k, fields[i]]));
  });
}

console.log(parseCsv(csv).map((h) => h.name).join(' '));

